export function installSeating({camera,blocked,lounges,extraSeats=[],onSit,onStand,watchCircus,openEldergroveStory=()=>false,openRiverbendStory=()=>false,openBuildersStory=()=>false,openBridgeStory=()=>false,openOfficeBoard=()=>false,openSquareBoard=()=>false,openGardenNotes=()=>false,openClubhouseBoard=()=>false,openLibraryReading=()=>false,openSchoolLesson=()=>false,watchRiverFestival=()=>false,riverFestivalActive=()=>false,takePhoto=()=>false,onFace=()=>{},onLookUp=()=>{}}){
 const seats=[];
 function add(name,x,z,y=1.4,yaw=Math.PI,dx=0,dz=1.5,kind='bench'){seats.push({name,x,z,y,yaw,approach:{x:x+dx,z:z+dz},kind});}
 for(const side of [-1,1])for(let z=22;z>-78;z-=15)if(z%2===0)add('Garden bench',side*12,z,1.5);
 for(const [x,z] of [[20,-17],[28,-17],[27,-7]])for(const offset of [-1.25,1.25])add("Lisa’s coffee chair",x+offset,z,1.35,Math.PI,0,1.3,'chair');
 for(const x of [-7,7])for(const dx of [-1.4,1.4])add('Roasted dining chair',x+dx,-88,1.32,Math.PI,0,1.3,'chair');
 for(const side of [-1,1])for(let i=0;i<3;i++)add('Circus audience bench',39+side*5.7,-65+i*2,1.5,side*Math.PI/2,-side*1.8,0,'circus');
 for(const s of lounges.spots)add(s.name+' bench',s.x,s.z-1.1,1.35,Math.PI,0,2.4,'lounge');
 seats.push(...extraSeats);
 for(const s of seats)if(blocked(s.approach.x,s.approach.z)){
  let found=false;for(let r=1.6;r<=3.6&&!found;r+=.4)for(let i=0;i<24&&!found;i++){const a=i*Math.PI/12,p={x:s.x+Math.sin(a)*r,z:s.z+Math.cos(a)*r};if(!blocked(p.x,p.z)){s.approach=p;found=true;}}
  if(!found)throw Error('Seat needs a clear approach: '+s.name);
 }
 const button=document.createElement('button');button.id='sitNearby';button.hidden=true;document.body.append(button);
 const dock=document.createElement('div');dock.id='seatControls';dock.hidden=true;document.body.append(dock);
 const label=document.createElement('span');const leave=document.createElement('button');leave.id='standFromSeat';leave.textContent='Stand up';
 const show=document.createElement('button');show.id='seatWatchCircus';show.textContent='Watch circus';show.onclick=watchCircus;dock.append(label,show,leave);
 const viewOptions=document.createElement('details');viewOptions.id='seatViewOptions';const viewTitle=document.createElement('summary');viewTitle.textContent='View options';const viewActions=document.createElement('div');const face=document.createElement('button');face.id='seatFaceForward';face.textContent='Face forward';face.onclick=()=>{if(!current||!enabled)return;onFace(current);viewOptions.open=false;};const photo=document.createElement('button');photo.id='seatPhoto';photo.textContent='Take photo';photo.onclick=()=>{if(!current||!enabled)return false;viewOptions.open=false;return takePhoto();};const lookUp=document.createElement('button');lookUp.id='seatLookUp';lookUp.textContent='Look up';lookUp.onclick=()=>{if(!current||!enabled)return;onLookUp();viewOptions.open=false;};const festival=document.createElement('button');festival.id='seatRiverFestival';festival.textContent='Start lantern boats';festival.hidden=true;festival.onclick=()=>{if(!enabled||current?.kind!=='riverbend'||riverFestivalActive())return false;const started=watchRiverFestival();if(started)viewOptions.open=false;return started;};const schoolLesson=document.createElement('button');schoolLesson.id='seatSchoolLesson';schoolLesson.textContent='Open lantern lesson';schoolLesson.hidden=true;schoolLesson.onclick=()=>{if(!enabled||current?.kind!=='school')return false;const opened=openSchoolLesson();if(opened)viewOptions.open=false;return opened;};viewActions.append(face,lookUp,photo,festival,schoolLesson);viewOptions.append(viewTitle,viewActions);dock.append(viewOptions);
 const reading=document.createElement('button');reading.id='seatLibraryReading';reading.textContent='Open library readings';reading.hidden=true;reading.onclick=()=>{if(!enabled||current?.kind!=='library')return false;const opened=openLibraryReading();if(opened)viewOptions.open=false;return opened;};viewActions.append(reading);
 const style=document.createElement('link');style.rel='stylesheet';style.href='seating.css';document.head.append(style);
 let current=null,nearest=null,exit=null,enabled=false;
 function clearLine(a,b){const n=Math.ceil(Math.hypot(a.x-b.x,a.z-b.z)/.2);for(let i=0;i<=n;i++){const t=n?i/n:0;if(blocked(a.x+(b.x-a.x)*t,a.z+(b.z-a.z)*t))return false;}return true;}
 function sit(){if(!enabled||current||!nearest)return false;const s=nearest;if(blocked(camera.position.x,camera.position.z)||!clearLine(camera.position,s.approach))return false;exit={x:camera.position.x,z:camera.position.z};onSit(s);current=s;viewOptions.open=false;button.hidden=true;dock.hidden=false;label.textContent=(s.kind==='bed'?'Resting · ':'Seated · ')+s.name;show.hidden=s.kind!=='circus';festival.hidden=s.kind!=='riverbend';schoolLesson.hidden=s.kind!=='school';return true;}
 function stand(){if(!current)return;const destination=exit&&!blocked(exit.x,exit.z)?exit:current.approach;current=null;viewOptions.open=false;dock.hidden=true;onStand(destination);}
 button.onclick=sit;leave.onclick=stand;
 const board=document.createElement('button');board.id='seatClubhouseBoard';board.textContent='Open Place Managers board';board.hidden=true;board.onclick=()=>{if(!enabled||current?.kind!=='clubhouse')return false;const opened=openClubhouseBoard();if(opened)viewOptions.open=false;return opened;};viewActions.append(board);
 const garden=document.createElement('button');garden.id='seatGardenNotes';garden.textContent='Open garden notes';garden.hidden=true;garden.onclick=()=>{if(!enabled||current?.kind!=='produce')return false;const opened=openGardenNotes();if(opened)viewOptions.open=false;return opened;};viewActions.append(garden);
 const square=document.createElement('button');square.id='seatSquareBoard';square.textContent='Open Town Square board';square.hidden=true;square.onclick=()=>{if(!enabled||current?.kind!=='square')return false;const opened=openSquareBoard();if(opened)viewOptions.open=false;return opened;};viewActions.append(square);
 const office=document.createElement('button');office.id='seatOfficeBoard';office.textContent='Open community project board';office.hidden=true;office.onclick=()=>{if(!enabled||current?.kind!=='office')return false;const opened=openOfficeBoard();if(opened)viewOptions.open=false;return opened;};viewActions.append(office);
 const bridgeStory=document.createElement('button');bridgeStory.id='seatBridgeStory';bridgeStory.textContent='Read Krown Bridge story';bridgeStory.hidden=true;bridgeStory.onclick=()=>{if(!enabled||current?.kind!=='bridge')return false;const opened=openBridgeStory();if(opened)viewOptions.open=false;return opened;};viewActions.append(bridgeStory);
 const buildersStory=document.createElement('button');buildersStory.id='seatBuildersStory';buildersStory.textContent='Read Making of Krownlandia';buildersStory.hidden=true;buildersStory.onclick=()=>{if(!enabled||current?.kind!=='builders')return false;const opened=openBuildersStory();if(opened)viewOptions.open=false;return opened;};viewActions.append(buildersStory);
 const riverStory=document.createElement('button');riverStory.id='seatRiverbendStory';riverStory.textContent='Read Riverbend stories';riverStory.hidden=true;riverStory.onclick=()=>{if(!enabled||current?.kind!=='riverbend')return false;const opened=openRiverbendStory();if(opened)viewOptions.open=false;return opened;};viewActions.append(riverStory);
 const elderStory=document.createElement('button');elderStory.id='seatEldergroveStory';elderStory.textContent='Read Eldergrove story';elderStory.hidden=true;elderStory.onclick=()=>{if(!enabled||current?.kind!=='eldergrove')return false;const opened=openEldergroveStory();if(opened)viewOptions.open=false;return opened;};viewActions.append(elderStory);
 const syncReading=()=>{elderStory.hidden=current?.kind!=='eldergrove';riverStory.hidden=current?.kind!=='riverbend';buildersStory.hidden=current?.kind!=='builders';bridgeStory.hidden=current?.kind!=='bridge';office.hidden=current?.kind!=='office';square.hidden=current?.kind!=='square';garden.hidden=current?.kind!=='produce';reading.hidden=current?.kind!=='library';board.hidden=current?.kind!=='clubhouse';};
 addEventListener('keydown',e=>{if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey||e.target?.closest?.('input,textarea,select,dialog,[contenteditable="true"]'))return;if(e.key.toLowerCase()==='f'&&!e.repeat&&enabled){if(current)stand();else sit();}});
 return {sit,stand,seats,get currentSeat(){return current},get active(){return !!current},get selected(){return nearest},update(available){enabled=available;syncReading();schoolLesson.hidden=current?.kind!=='school';festival.hidden=current?.kind!=='riverbend';festival.disabled=riverFestivalActive();festival.textContent=festival.disabled?'Lantern boats playing':'Start lantern boats';if(!available)viewOptions.open=false;nearest=null;let best=2; if(available&&!current)for(const s of seats){const d=Math.hypot(camera.position.x-s.approach.x,camera.position.z-s.approach.z);if(d<best&&clearLine(camera.position,s.approach)){best=d;nearest=s;}}button.hidden=!nearest||!!current;button.textContent=nearest?'F · '+(nearest.kind==='bed'?'Rest':'Sit')+' · '+nearest.name:'';dock.hidden=!current||!available;}};
}
